// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    bytes32[3] roles;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
        roles[0] = c.TIMELOCK_ADMIN_ROLE();
        roles[1] = c.PROPOSER_ROLE();
        roles[2] = c.EXECUTOR_ROLE();
    }

    function testFuzz_property(uint8 roleIndex, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        bytes32 role = roles[bound(roleIndex, 0, 2)];

        // deployer holds TIMELOCK_ADMIN_ROLE (admin of all three roles); grant actor the role
        c.grantRole(role, actor);
        assertTrue(c.hasRole(role, actor), "precondition: actor holds role");

        // actor renounces the role for themselves
        vm.prank(actor);
        c.renounceRole(role, actor);

        // GENERAL RULE: renouncing a role revokes it from the caller
        assertTrue(!c.hasRole(role, actor), "renouncing must revoke the role");
    }
}
